import{c as a,Q as h,j as o,m as t}from"./chunks/framework.BSpkaxTm.js";const d=JSON.parse('{"title":"Bắt đầu với Novela","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),c={name:"guide/index.md"};function i(u,n,g,l,e,r){return h(),o("div",null,[...n[0]||(n[0]=[t('<h1 id="bat-đau-voi-novela" tabindex="-1">Bắt đầu với Novela <a class="header-anchor" href="#bat-đau-voi-novela" aria-label="Permalink to &quot;Bắt đầu với Novela&quot;">​</a></h1><p>Novela là trình đọc sách và truyện cho Android theo giao diện Material 3. Ứng dụng không kèm nội dung sẵn — bạn tự thêm sách, nguồn truyện và cách đọc của mình.</p><nav class="table-of-contents"><ul><li><a href="#cai-đat">Cài đặt</a></li><li><a href="#them-sach-vao-tu">Thêm sách vào tủ</a><ul><li><a href="#sach-trong-may">Sách trong máy</a></li><li><a href="#nguon-sach-truc-tuyen">Nguồn sách trực tuyến</a></li><li><a href="#rss">RSS</a></li></ul></li><li><a href="#đoc-va-nghe">Đọc và nghe</a></li><li><a href="#sao-luu-va-đong-bo">Sao lưu và đồng bộ</a></li><li><a href="#cap-nhat">Cập nhật</a></li><li><a href="#cau-hoi-thuong-gap">Câu hỏi thường gặp</a><ul><li><a href="#vi-sao-lan-đau-mo-ung-dung-khong-co-sach">Vì sao lần đầu mở ứng dụng không có sách?</a></li><li><a href="#nguon-sach-bao-khong-hop-le-thi-co-dung-đuoc-khong">Nguồn sách báo &quot;không hợp lệ&quot; thì có dùng được không?</a></li><li><a href="#chu-bi-thieu-hoac-cach-dong-la">Chữ bị thiếu hoặc cách dòng lạ?</a></li><li><a href="#lam-sao-chuyen-du-lieu-sang-may-moi">Làm sao chuyển dữ liệu sang máy mới?</a></li><li><a href="#lam-sao-doc-truyen-online">Làm sao để đọc truyện online?</a></li></ul></li></ul></nav><h2 id="cai-đat" tabindex="-1">Cài đặt <a class="header-anchor" href="#cai-đat" aria-label="Permalink to &quot;Cài đặt&quot;">​</a></h2><ol><li>Mở trang <a href="/novela-app/download.html">Tải xuống</a> và tải gói APK cho máy 64-bit.</li><li>Mở tệp APK, bật quyền cài ứng dụng từ nguồn không xác định nếu Android yêu cầu.</li><li>Cài đặt và mở Novela.</li></ol><p>Novela yêu cầu Android 8.0 trở lên. Khi nâng cấp, cài đè lên bản cũ để giữ nguyên dữ liệu.</p><h2 id="them-sach-vao-tu" tabindex="-1">Thêm sách vào tủ <a class="header-anchor" href="#them-sach-vao-tu" aria-label="Permalink to &quot;Thêm sách vào tủ&quot;">​</a></h2><h3 id="sach-trong-may" tabindex="-1">Sách trong máy <a class="header-anchor" href="#sach-trong-may" aria-label="Permalink to &quot;Sách trong máy&quot;">​</a></h3><ul><li>Mở tệp <code>.epub</code>, <code>.txt</code>, <code>.mobi</code> hoặc <code>.pdf</code> bằng Novela từ trình quản lý tệp, hoặc</li><li>Trong màn hình <strong>Tủ sách</strong>, mở menu và chọn <strong>Thêm sách</strong>, sau đó chọn tệp trong máy.</li></ul><p>Nếu ứng dụng không thấy tệp, kiểm tra quyền truy cập bộ nhớ trong phần cài đặt Android.</p><h3 id="nguon-sach-truc-tuyen" tabindex="-1">Nguồn sách trực tuyến <a class="header-anchor" href="#nguon-sach-truc-tuyen" aria-label="Permalink to &quot;Nguồn sách trực tuyến&quot;">​</a></h3><p>Novela dùng nguồn sách dạng JSON theo chuẩn Legado.</p><ol><li>Mở <strong>Nguồn sách → Quản lý nguồn</strong>.</li><li>Chọn <strong>Nhập nguồn sách</strong> và dán nội dung JSON, hoặc chọn tệp nguồn trong máy.</li><li>Lưu lại, sau đó tìm truyện trong mục <strong>Khám phá</strong> hoặc dùng tìm kiếm.</li></ol><p>Một số nguồn có thể không còn hoạt động. Khi gặp lỗi, thử nguồn khác hoặc mở nguồn đó ra để kiểm tra lại quy tắc — quy tắc đọc viết bằng JavaScript, XPath hoặc regex ngay trong ứng dụng.</p><h3 id="rss" tabindex="-1">RSS <a class="header-anchor" href="#rss" aria-label="Permalink to &quot;RSS&quot;">​</a></h3><p>Mở <strong>Nguồn RSS</strong>, thêm nguồn cấp bằng URL feed. Novela dùng cùng giao diện đọc cho bài RSS và sách.</p><h2 id="đoc-va-nghe" tabindex="-1">Đọc và nghe <a class="header-anchor" href="#đoc-va-nghe" aria-label="Permalink to &quot;Đọc và nghe&quot;">​</a></h2><ul><li>Chạm vào giữa màn hình để mở thanh công cụ đọc.</li><li>Mở <strong>Cài đặt đọc</strong> để đổi phông chữ, cỡ chữ, lề, khoảng cách dòng, màu nền và hiệu ứng lật trang.</li><li>Chế độ tối và E-Ink có trong phần cài đặt giao diện.</li><li>Chọn <strong>Đọc to</strong> để nghe bằng TTS hệ thống hoặc TTS trực tuyến đã cấu hình.</li><li>Trong màn hình đọc, dùng <strong>Dịch chương</strong> hoặc bôi đen một từ để <strong>Dịch từ</strong> khi gặp ngoại văn.</li><li>Mục <strong>Cộng đồng</strong> để xem truyện và bộ nguồn mọi người chia sẻ, cài thẳng vào ứng dụng.</li></ul><p>Tiến độ đọc, dấu trang và lịch sử được lưu tự động cho từng sách.</p><h2 id="sao-luu-va-đong-bo" tabindex="-1">Sao lưu và đồng bộ <a class="header-anchor" href="#sao-luu-va-đong-bo" aria-label="Permalink to &quot;Sao lưu và đồng bộ&quot;">​</a></h2><p>Vào <strong>Cài đặt → Sao lưu và khôi phục</strong> để:</p><ul><li>Xuất bản sao lưu ra tệp trong máy.</li><li>Kết nối WebDAV hoặc Google Drive để sao lưu trên máy chủ từ xa.</li><li>Khôi phục dữ liệu trên thiết bị mới.</li></ul><p>Nên sao lưu trước khi cài lại ứng dụng hoặc đổi điện thoại.</p><h2 id="cap-nhat" tabindex="-1">Cập nhật <a class="header-anchor" href="#cap-nhat" aria-label="Permalink to &quot;Cập nhật&quot;">​</a></h2><p>Vào <strong>Cài đặt → Giới thiệu</strong> rồi chọn <strong>Kiểm tra cập nhật</strong>. Khi có bản mới, ứng dụng tải APK và mở trình cài đặt của Android; cài đè giữ nguyên dữ liệu. Bạn cần hỗ trợ thêm thì hỏi trong <a href="https://zalo.me/g/53swywolqkq95enm6t7d" target="_blank" rel="noopener noreferrer">nhóm Zalo của cộng đồng</a>.</p><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><h3 id="vi-sao-lan-đau-mo-ung-dung-khong-co-sach" tabindex="-1">Vì sao lần đầu mở ứng dụng không có sách? <a class="header-anchor" href="#vi-sao-lan-đau-mo-ung-dung-khong-co-sach" aria-label="Permalink to &quot;Vì sao lần đầu mở ứng dụng không có sách?&quot;">​</a></h3><p>Novela không kèm nội dung. Hãy thêm sách trong máy hoặc nhập nguồn sách trước.</p><h3 id="nguon-sach-bao-khong-hop-le-thi-co-dung-đuoc-khong" tabindex="-1">Nguồn sách báo &quot;không hợp lệ&quot; thì có dùng được không? <a class="header-anchor" href="#nguon-sach-bao-khong-hop-le-thi-co-dung-đuoc-khong" aria-label="Permalink to &quot;Nguồn sách báo &quot;không hợp lệ&quot; thì có dùng được không?&quot;">​</a></h3><p>Kiểm tra nguồn chỉ mang tính tham khảo. Một nguồn báo lỗi vẫn có thể đọc được nếu trang nguồn đổi cấu trúc; ngược lại, nguồn hợp lệ vẫn có thể hỏng khi trang nguồn thay đổi.</p><h3 id="chu-bi-thieu-hoac-cach-dong-la" tabindex="-1">Chữ bị thiếu hoặc cách dòng lạ? <a class="header-anchor" href="#chu-bi-thieu-hoac-cach-dong-la" aria-label="Permalink to &quot;Chữ bị thiếu hoặc cách dòng lạ?&quot;">​</a></h3><p>Tắt quy tắc thay thế/xử lý văn bản đang bật rồi mở lại chương. Nếu vẫn lỗi, kiểm tra nội dung gốc trên trang nguồn.</p><h3 id="lam-sao-chuyen-du-lieu-sang-may-moi" tabindex="-1">Làm sao chuyển dữ liệu sang máy mới? <a class="header-anchor" href="#lam-sao-chuyen-du-lieu-sang-may-moi" aria-label="Permalink to &quot;Làm sao chuyển dữ liệu sang máy mới?&quot;">​</a></h3><p>Sao lưu lên WebDAV hoặc xuất tệp sao lưu, sau đó khôi phục trên máy mới trước khi thêm sách.</p><h3 id="lam-sao-doc-truyen-online" tabindex="-1">Làm sao để đọc truyện online? <a class="header-anchor" href="#lam-sao-doc-truyen-online" aria-label="Permalink to &quot;Làm sao để đọc truyện online?&quot;">​</a></h3><p>Thêm nguồn sách dạng JSON theo chuẩn Legado, mở mục Khám phá rồi chọn truyện. Đọc được hay không tuỳ trang nguồn còn hoạt động.</p>',36)])])}const m=a(c,[["render",i]]);export{d as __pageData,m as default};
